19	export async function handleReadSymbols(
20	  args: ReadSymbolsArgs,
21	  projectRoot: string,
22	  symbolResolver: SymbolResolver,
23	  fileCache: FileCache,
24	  contextRegistry: ContextRegistry,
25	  astIndex?: AstIndexClient,
26	  advisoryReminders = true,
27	): Promise<{ content: Array<{ type: "text"; text: string }> }> {
28	  const absPath = resolveSafePath(projectRoot, args.path);
29	
30	  // Get file content ONCE
31	  const cached = fileCache.get(absPath);
32	  let lines: string[];
33	
34	  if (cached) {
35	    lines = cached.lines;
36	  } else {
37	    const content = await readFile(absPath, "utf-8");
38	    lines = content.split("\n");
39	  }
40	
41	  // Get AST structure ONCE
42	  const structure = await structureFor(cached, absPath, astIndex);
43	
44	  const N = args.symbols.length;
45	  const sections: string[] = [];
46	
47	  // v0.24.1 — anti-pattern guard. When the caller requests most of the
48	  // symbols in the file, a batch read costs more than one smart_read.
49	  // Earlier versions used sum(lineCount), but ast-index parser bugs
50	  // (arrow functions / export function / Vue SFC / TS types) return
51	  // overlapping ranges that inflate the sum and let the guard miss. The
52	  // count-based check (requested symbols / total top-level symbols) is
53	  // immune to those parser issues.
54	  if (structure && structure.symbols && structure.symbols.length >= 3) {
55	    const uniqueRequested = new Set(args.symbols.map((s) => s.split(".")[0]));
56	    const matchedTopLevel = structure.symbols.filter((s) =>
57	      uniqueRequested.has(s.name),
58	    );
59	    const total = structure.symbols.length;
60	    if (matchedTopLevel.length >= 3 && matchedTopLevel.length / total >= 0.7) {
61	      const text =
62	        `FILE: ${args.path} | SYMBOLS: ${N} requested\n\n` +
63	        `ADVISORY: You requested ${matchedTopLevel.length}/${total} symbols ` +
64	        `(≥70% of the file's top-level symbols). A batch read here costs ` +
65	        `more than reading the whole file once.\n\n` +
66	        `Cheaper alternatives:\n` +
67	        `  - smart_read("${args.path}") for a structural overview\n` +
68	        `  - read_for_edit("${args.path}", "<symbol>") when you need exact edit context\n` +
69	        `  - Raw Read with offset/limit for a specific range\n\n` +
70	        `If you truly need every body, call read_symbols with a narrower list ` +
71	        `or use raw Read (bounded).`;
72	      return { content: [{ type: "text", text }] };
73	    }
